import React, { useEffect, useState, useCallback } from 'react';
import { useAuth } from '../context/AuthContext';
import { reproductionService, animalService } from '../services/api';
import { Baby, Heart, Calendar, ArrowRight, Info } from 'lucide-react';
import toast from 'react-hot-toast';
import SemenInventoryPanel from '../components/modules/SemenInventoryPanel';

const ESTRUS_SIGNS = {
  bleeding: 'Kanama',
  behavior_change: 'Davranış Değişimi',
  swelling: 'Şişme',
  discharge: 'Akıntı',
  vocalizing: 'Ses Çıkarma',
  standing_heat: 'Durma Refleksi'
};

const GESTATION_PERIODS = {
  'Keçi': 150,
  'Koyun': 150,
  'Sığır': 283,
  'Manda': 310,
  'Deve': 390
};

export default function ReproductionPage() {
  const { user } = useAuth();
  const farmId = user?.farm_id;

  const [records, setRecords] = useState([]);
  const [animals, setAnimals] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('estrus'); // estrus, mating, birth
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({
    animal_id: '',
    record_date: new Date().toISOString().split('T')[0],
    mating_animal_id: '',
    offspring_count: 1,
    birth_type: 'normal',
    notes: '',
    expected_birth_date: ''
  });

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const [recRes, animRes] = await Promise.all([
        reproductionService.list(farmId),
        animalService.list(farmId, 1, 100, { status: 'active', gender: 'F' })
      ]);
      setRecords(recRes.data.data || []);
      setAnimals(animRes.data.data || []);
    } catch {
      toast.error('Veriler yüklenemedi');
    } finally {
      setLoading(false);
    }
  }, [farmId]);

  useEffect(() => { load(); }, [load]);

  const calculateExpectedBirth = (matingDate, species) => {
    if (!matingDate || !species) return '';
    const date = new Date(matingDate);
    const days = GESTATION_PERIODS[species] || 280;
    date.setDate(date.getDate() + days);
    return date.toISOString().split('T')[0];
  };

  const handleAnimalChange = (animalId) => {
    const animal = animals.find(a => a.id === parseInt(animalId));
    const expected = (activeTab === 'mating' && animal) 
      ? calculateExpectedBirth(form.record_date, animal.species)
      : '';
    
    setForm({ ...form, animal_id: animalId, expected_birth_date: expected });
  };

  const handleAdd = async (e) => {
    e.preventDefault();
    if (!form.animal_id) {
      toast.error('Hayvan seçimi zorunlu');
      return;
    }
    try {
      const payload = {
        animal_id: parseInt(form.animal_id, 10),
        farm_id: farmId,
        record_type: activeTab,
        record_date: form.record_date,
        notes: form.notes || null,
        expected_birth_date: form.expected_birth_date || null,
        ...(activeTab === 'mating' && form.mating_animal_id ? { mating_animal_id: parseInt(form.mating_animal_id, 10) } : {}),
        ...(activeTab === 'birth' ? {
          offspring_count: parseInt(form.offspring_count, 10) || 1,
          birth_type: ['normal', 'assisted', 'cesarean'].includes(form.birth_type) ? form.birth_type : 'normal'
        } : {})
      };
      await reproductionService.create(farmId, payload);
      toast.success('Kayıt başarıyla eklendi');
      setShowForm(false);
      resetForm();
      load();
    } catch (err) {
      toast.error(err.response?.data?.error || 'İşlem başarısız');
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Bu üreme kaydını silmek istediğinize emin misiniz?')) return;
    try {
      await reproductionService.delete(farmId, id);
      toast.success('Kayıt silindi');
      load();
    } catch (err) {
      toast.error(err.response?.data?.error || 'Kayıt silinemedi');
    }
  };

  const resetForm = () => {
    setForm({
      animal_id: '',
      record_date: new Date().toISOString().split('T')[0],
      mating_animal_id: '',
      offspring_count: 1,
      birth_type: 'normal',
      notes: '',
      expected_birth_date: ''
    });
  };

  const filteredRecords = records.filter(r => r.record_type === activeTab);

  const renderForm = () => {
    return (
      <form onSubmit={handleAdd} className="space-y-4 animate-in fade-in slide-in-from-top-4 duration-300">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-xs font-bold text-gray-400 uppercase mb-1">Hayvan Seçin</label>
            <select
              value={form.animal_id}
              onChange={e => handleAnimalChange(e.target.value)}
              className="input-field"
              required
            >
              <option value="">Hayvan Seçin...</option>
              {animals.map(a => (
                <option key={a.id} value={a.id}>{a.name} ({a.code}) - {a.species}</option>
              ))}
            </select>
          </div>
          <div>
            <label className="block text-xs font-bold text-gray-400 uppercase mb-1">Kayıt Tarihi</label>
            <input
              type="date"
              value={form.record_date}
              onChange={e => {
                const date = e.target.value;
                const animal = animals.find(a => a.id === parseInt(form.animal_id));
                const expected = (activeTab === 'mating' && animal) 
                  ? calculateExpectedBirth(date, animal.species)
                  : '';
                setForm({ ...form, record_date: date, expected_birth_date: expected });
              }}
              className="input-field"
              required
            />
          </div>
        </div>

        {activeTab === 'estrus' && (
          <div className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm">
            <p className="text-sm font-bold text-gray-700 mb-3">Dönem Belirtileri</p>
            <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
              {Object.entries(ESTRUS_SIGNS).map(([key, label]) => (
                <label key={key} className="flex items-center gap-2 cursor-pointer group">
                  <input
                    type="checkbox"
                    checked={form.description?.includes(key)}
                    onChange={e => {
                      const signs = form.description ? form.description.split(',') : [];
                      if (e.target.checked) {
                        signs.push(key);
                      } else {
                        const idx = signs.indexOf(key);
                        if (idx > -1) signs.splice(idx, 1);
                      }
                      setForm({ ...form, description: signs.filter(Boolean).join(',') });
                    }}
                    className="w-4 h-4 rounded text-green-600 focus:ring-green-500"
                  />
                  <span className="text-sm text-gray-600 group-hover:text-green-700 transition-colors">{label}</span>
                </label>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'mating' && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-bold text-gray-400 uppercase mb-1">Erkek Hayvan ID/Kod</label>
              <input
                type="number"
                placeholder="Örn: 2"
                value={form.mating_animal_id}
                onChange={e => setForm({ ...form, mating_animal_id: e.target.value })}
                className="input-field"
              />
            </div>
            <div>
              <label className="block text-xs font-bold text-gray-400 uppercase mb-1">Tahmini Doğum Tarihi</label>
              <div className="input-field bg-gray-50 flex items-center gap-2">
                <Calendar className="w-4 h-4 text-green-600" />
                <span className="font-semibold text-green-800">{form.expected_birth_date || '—'}</span>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'birth' && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-bold text-gray-400 uppercase mb-1">Yavru Sayısı</label>
              <input
                type="number"
                min="1"
                placeholder="1"
                value={form.offspring_count}
                onChange={e => setForm({ ...form, offspring_count: e.target.value })}
                className="input-field"
              />
            </div>
            <div>
              <label className="block text-xs font-bold text-gray-400 uppercase mb-1">Doğum Sonucu</label>
              <select
                value={form.birth_type}
                onChange={e => setForm({ ...form, birth_type: e.target.value })}
                className="input-field"
              >
                <option value="normal">Normal Doğum</option>
                <option value="assisted">Destekli Doğum</option>
                <option value="cesarean">Sezaryen</option>
              </select>
            </div>
          </div>
        )}

        <textarea
          placeholder="Ek notlar veya detaylar..."
          value={form.notes}
          onChange={e => setForm({ ...form, notes: e.target.value })}
          className="input-field"
          rows={2}
        />
        
        <div className="flex gap-3">
          <button type="button" onClick={() => {setShowForm(false); resetForm();}} className="btn-secondary flex-1">İptal</button>
          <button type="submit" className="btn-primary flex-1">Kaydı Tamamla</button>
        </div>
      </form>
    );
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">🧬 Üreme Yönetimi</h1>
          <p className="text-sm text-gray-500">Gebelik takibi ve doğum kayıtları</p>
        </div>
        <button 
          onClick={() => {setShowForm(!showForm); if(!showForm) resetForm();}} 
          className={`btn-primary flex items-center gap-2 ${showForm ? 'bg-red-500 hover:bg-red-600' : ''}`}
        >
          {showForm ? 'İptal' : <><ArrowRight className="w-4 h-4" /> Yeni Kayıt</>}
        </button>
      </div>

      {/* Tabs */}
      <div className="flex bg-white p-1 rounded-2xl shadow-sm border border-gray-100 overflow-x-auto no-scrollbar">
        {[
          { id: 'estrus', label: 'Dönem', icon: Heart, color: 'text-red-500' },
          { id: 'mating', label: 'Çiftleştirme', icon: Baby, color: 'text-blue-500' },
          { id: 'birth', label: 'Doğum', icon: ArrowRight, color: 'text-green-500' }
        ].map(tab => (
          <button
            key={tab.id}
            onClick={() => {setActiveTab(tab.id); setShowForm(false);}}
            className={`flex-1 flex items-center justify-center gap-2 px-4 py-3 rounded-xl text-sm font-bold transition-all whitespace-nowrap ${
              activeTab === tab.id
                ? 'bg-green-50 text-green-700 shadow-sm'
                : 'text-gray-500 hover:bg-gray-50'
            }`}
          >
            <tab.icon className={`w-4 h-4 ${activeTab === tab.id ? tab.color : 'text-gray-400'}`} />
            {tab.label}
          </button>
        ))}
      </div>

      {showForm && (
        <div className="card border-green-100 bg-green-50/20">
          <h2 className="text-lg font-bold mb-4 flex items-center gap-2">
            <Info className="w-5 h-5 text-green-600" />
            Yeni {activeTab === 'estrus' ? 'Dönem Belirtisi' : activeTab === 'mating' ? 'Çiftleştirme Kaydı' : 'Doğum Kaydı'}
          </h2>
          {renderForm()}
        </div>
      )}

      {/* Content */}
      <div className="space-y-4">
        {loading ? (
          <div className="flex items-center justify-center h-64 bg-white rounded-3xl">
            <div className="w-10 h-10 border-4 border-green-600 border-t-transparent rounded-full animate-spin" />
          </div>
        ) : filteredRecords.length === 0 ? (
          <div className="text-center py-20 bg-white rounded-3xl border border-dashed border-gray-200">
            <div className="text-6xl mb-4 opacity-20">🧬</div>
            <p className="text-gray-500 font-medium">Henüz kayıt bulunamadı</p>
            <button onClick={() => setShowForm(true)} className="mt-4 text-green-600 font-bold hover:underline">
              İlk kaydı ekleyin →
            </button>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {filteredRecords.map(r => (
              <div key={r.id} className="card group hover:scale-[1.02] transition-transform">
                <div className="flex justify-between items-start mb-4">
                  <div className="bg-green-100 text-green-700 px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider">
                    {r.record_date}
                  </div>
                  <button 
                    onClick={() => handleDelete(r.id)}
                    className="text-gray-300 hover:text-red-500 transition-colors"
                    title="Kaydı Sil"
                  >
                    ✕
                  </button>
                </div>
                
                <div className="flex items-center gap-4 mb-4 pb-4 border-b border-gray-50">
                   <div className="w-12 h-12 bg-gray-50 rounded-2xl flex items-center justify-center text-xl shadow-inner">
                    🆔
                   </div>
                   <div>
                     <p className="text-[10px] text-gray-400 font-bold uppercase">Hayvan Bilgisi</p>
                     <p className="font-bold text-gray-900">ID: #{r.animal_id}</p>
                   </div>
                </div>

                <div className="space-y-3">
                  {activeTab === 'estrus' && (
                    <div>
                      <p className="text-[10px] text-gray-400 font-bold uppercase mb-1">Belirtiler</p>
                      <div className="flex flex-wrap gap-1">
                        {r.description?.split(',').map(s => (
                          <span key={s} className="bg-red-50 text-red-600 px-2 py-0.5 rounded-md text-[10px] font-medium">
                            {ESTRUS_SIGNS[s] || s}
                          </span>
                        ))}
                      </div>
                    </div>
                  )}

                  {activeTab === 'mating' && (
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <p className="text-[10px] text-gray-400 font-bold uppercase">Erkek ID</p>
                        <p className="text-sm font-bold text-blue-700">{r.description || '—'}</p>
                      </div>
                      <div>
                        <p className="text-[10px] text-gray-400 font-bold uppercase">Tahmini Doğum</p>
                        <p className="text-sm font-bold text-orange-600">{r.expected_birth_date || 'Bilinmiyor'}</p>
                      </div>
                    </div>
                  )}

                  {activeTab === 'birth' && (
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <p className="text-[10px] text-gray-400 font-bold uppercase">Yavru Sayısı</p>
                        <p className="text-lg font-bold text-green-700">{r.description || '1'}</p>
                      </div>
                      <div>
                        <p className="text-[10px] text-gray-400 font-bold uppercase">Sonuç</p>
                        <p className="text-sm font-bold text-gray-700 capitalize">{r.notes || 'Normal'}</p>
                      </div>
                    </div>
                  )}

                  {r.notes && activeTab !== 'birth' && (
                    <div className="bg-gray-50 p-2 rounded-xl">
                      <p className="text-[10px] text-gray-400 font-bold uppercase mb-1">Notlar</p>
                      <p className="text-xs text-gray-600 italic">"{r.notes}"</p>
                    </div>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Dondurulmuş Sperm Payet Deposu & Nitrojen Tankı Envanteri */}
      <SemenInventoryPanel />
    </div>
  );
}
